<?php require __DIR__.'/ui.php';role(['admin','gerente','vendedor','producao']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO events(title,event_type,start_at,end_at,budget,status,notes)VALUES(?,?,?,?,?,?,?)")->execute([$_POST['title'],$_POST['event_type'],$_POST['start_at'],$_POST['end_at'],$_POST['budget'],$_POST['status'],$_POST['notes']]);go('events.php');}$rows=$p->query("SELECT * FROM events ORDER BY start_at")->fetchAll();page_head('Eventos e grandes encomendas');?><div class="grid g2"><div class="card"><form method="post"><?=csrf_field()?><label>Evento</label><input name="title" required><label>Tipo</label><select name="event_type"><option>Casamento</option><option>Aniversário</option><option>Corporativo</option><option>Decoração</option><option>Outro</option></select><label>Início</label><input type="datetime-local" name="start_at"><label>Fim</label><input type="datetime-local" name="end_at"><label>Orçamento</label><input type="number" step=".01" name="budget"><label>Status</label><select name="status"><option>Planejamento</option><option>Orçamento</option><option>Confirmado</option><option>Execução</option><option>Concluído</option></select><label>Notas</label><textarea name="notes"></textarea><button class="primary">Salvar</button></form></div><div class="card"><table><tr><th>Evento</th><th>Data</th><th>Orçamento</th><th>Status</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['title'])?><small><?=e($x['event_type'])?></small></td><td><?=$x['start_at']?></td><td><?=money($x['budget'])?></td><td><?=$x['status']?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>